var renderer=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).First(r=>r.name=="PlantPot");var material=renderer.sharedMaterial;
return new{bounds=renderer.bounds.size.ToString(),textures=material.GetTexturePropertyNames().Select(p=>new{property=p,texture=material.GetTexture(p)==null?null:material.GetTexture(p).name}).ToArray(),properties=Enumerable.Range(0,material.shader.GetPropertyCount()).Select(i=>new{name=material.shader.GetPropertyName(i),type=material.shader.GetPropertyType(i).ToString()}).ToArray()};
